import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>
#include <cstdint>

// Single fused kernel: tiled direct 2D convolution (stride/padding/dilation aware).
// Each block handles a 16x16 output tile for one (batch, out_channel) pair.
// The weights for that out_channel and the input halo tiles are staged in
// shared memory and reused by all threads in the block.
__global__ void conv2d_forward_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C_in, int H, int W,
    int C_out, int H_out, int W_out,
    int K, int stride, int pad, int dil)
{
    extern __shared__ float smem[];

    const int tid      = threadIdx.y * blockDim.x + threadIdx.x;
    const int nthreads = blockDim.x * blockDim.y;

    const int oc = blockIdx.z % C_out;
    const int n  = blockIdx.z / C_out;

    // Stage this output channel's weights into shared memory.
    const int wsize = C_in * K * K;
    float* s_w = smem;
    for (int i = tid; i < wsize; i += nthreads)
        s_w[i] = weight[(int64_t)oc * wsize + i];

    // Input tile geometry (covers the block's outputs plus the halo).
    const int halo  = dil * (K - 1);
    const int tileW = (blockDim.x - 1) * stride + halo + 1;
    const int tileH = (blockDim.y - 1) * stride + halo + 1;
    float* s_in = smem + wsize;

    const int base_h = blockIdx.y * blockDim.y * stride - pad;
    const int base_w = blockIdx.x * blockDim.x * stride - pad;

    const int ow = blockIdx.x * blockDim.x + threadIdx.x;
    const int oh = blockIdx.y * blockDim.y + threadIdx.y;
    const bool active = (ow < W_out) && (oh < H_out);

    float acc = (bias != nullptr) ? bias[oc] : 0.0f;

    const float* in_nc = input + (int64_t)n * C_in * H * W;

    for (int ic = 0; ic < C_in; ++ic) {
        // Cooperatively load the (zero-padded) input tile for this channel.
        const float* in_c = in_nc + (int64_t)ic * H * W;
        for (int i = tid; i < tileH * tileW; i += nthreads) {
            const int th = i / tileW;
            const int tw = i % tileW;
            const int ih = base_h + th;
            const int iw = base_w + tw;
            float v = 0.0f;
            if (ih >= 0 && ih < H && iw >= 0 && iw < W)
                v = in_c[(int64_t)ih * W + iw];
            s_in[i] = v;
        }
        __syncthreads();

        if (active) {
            const float* s_w_ic = s_w + ic * K * K;
            const int sh = threadIdx.y * stride;
            const int sw = threadIdx.x * stride;
            float a = 0.0f;
            for (int kh = 0; kh < K; ++kh) {
                const int row = (sh + kh * dil) * tileW + sw;
                for (int kw = 0; kw < K; ++kw)
                    a += s_in[row + kw * dil] * s_w_ic[kh * K + kw];
            }
            acc += a;
        }
        __syncthreads();
    }

    if (active)
        output[((int64_t)(n * C_out + oc) * H_out + oh) * W_out + ow] = acc;
}

torch::Tensor conv2d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    int64_t stride, int64_t pad, int64_t dil)
{
    TORCH_CHECK(input.is_cuda() && weight.is_cuda(), "input and weight must be CUDA tensors");
    TORCH_CHECK(input.scalar_type() == torch::kFloat32, "only float32 supported");

    auto input_c  = input.contiguous();
    auto weight_c = weight.contiguous();

    const int N     = input_c.size(0);
    const int C_in  = input_c.size(1);
    const int H     = input_c.size(2);
    const int W     = input_c.size(3);
    const int C_out = weight_c.size(0);
    const int K     = weight_c.size(2);

    const int H_out = (H + 2 * (int)pad - (int)dil * (K - 1) - 1) / (int)stride + 1;
    const int W_out = (W + 2 * (int)pad - (int)dil * (K - 1) - 1) / (int)stride + 1;

    auto output = torch::empty({N, C_out, H_out, W_out}, input_c.options());

    const int bx = 16, by = 16;
    dim3 block(bx, by);
    dim3 grid((W_out + bx - 1) / bx, (H_out + by - 1) / by, N * C_out);

    const int halo  = (int)dil * (K - 1);
    const int tileW = (bx - 1) * (int)stride + halo + 1;
    const int tileH = (by - 1) * (int)stride + halo + 1;
    const size_t smem = ((size_t)C_in * K * K + (size_t)tileW * tileH) * sizeof(float);

    torch::Tensor bias_c;
    const float* bias_ptr = nullptr;
    if (bias.has_value() && bias->defined()) {
        bias_c = bias->contiguous();
        bias_ptr = bias_c.data_ptr<float>();
    }

    if (smem > 48 * 1024) {
        cudaFuncSetAttribute(conv2d_forward_kernel,
                             cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem);
    }
    conv2d_forward_kernel<<<grid, block, smem, at::cuda::getCurrentCUDAStream()>>>(
        input_c.data_ptr<float>(),
        weight_c.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        N, C_in, H, W,
        C_out, H_out, W_out,
        K, (int)stride, (int)pad, (int)dil);

    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return output;
}
"""

cpp_src = r"""
#include <torch/extension.h>
torch::Tensor conv2d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    int64_t stride, int64_t pad, int64_t dil);
"""

_ext = load_inline(
    name="conv2d_tiled_ext",
    cpp_sources=cpp_src,
    cuda_sources=cuda_src,
    functions=["conv2d_forward"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    2D convolution backed by a single custom CUDA kernel (tiled direct conv
    with shared-memory staging of weights and input halo tiles).
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, dilation: int = 1,
                 groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        assert groups == 1, "custom kernel supports groups == 1"
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.conv2d = nn.Conv2d(in_channels, out_channels, (kernel_size, kernel_size),
                                stride=stride, padding=padding, dilation=dilation,
                                groups=groups, bias=bias)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if not x.is_cuda:
            return self.conv2d(x)
        return _ext.conv2d_forward(
            x, self.conv2d.weight, self.conv2d.bias,
            self.stride, self.padding, self.dilation)

